[tasks.prepare-real-common-cohort]
shell = "node --input-type=module-typescript -e"
run = '''
const {execFileSync}=await import('node:child_process');
const {readFileSync,writeFileSync,existsSync,realpathSync}=await import('node:fs');
const {join}=await import('node:path');
const {homedir}=await import('node:os');
const {createHash}=await import('node:crypto');
const {strict:assert}=await import('node:assert');
assert(!existsSync('real-common-cohort-candidate.json'),'Reconcile the existing publication candidate instead of creating another cohort');
const frozen=JSON.parse(readFileSync('frozen-case-registration.json','utf8'));
const publication=JSON.parse(readFileSync('frozen-harness-publication.json','utf8'));
assert(publication.complete);assert.equal(publication.receipts.length,6);
for(const [key,harness] of Object.entries(frozen.harnesses)){const receipt=publication.receipts.find(row=>row.key===key);assert(receipt?.clean);assert.equal(receipt.remoteRevision,harness.harnessRevision);assert.equal(execFileSync('git',['rev-parse','HEAD'],{cwd:harness.worktree,encoding:'utf8'}).trim(),harness.harnessRevision);assert.equal(execFileSync('git',['status','--porcelain'],{cwd:harness.worktree,encoding:'utf8'}),'')}
const main=join(homedir(),'Monochromatic');
assert.equal(realpathSync(main),realpathSync(execFileSync('git',['rev-parse','--show-toplevel'],{cwd:main,encoding:'utf8'}).trim()));assert.equal(execFileSync('git',['branch','--show-current'],{cwd:main,encoding:'utf8'}).trim(),'main');
const preparedAt=new Date().toISOString();
const cohortId='complete-'+preparedAt.replaceAll(/[-:.]/gu,'');
assert.match(cohortId,/^[A-Za-z0-9._-]{1,128}$/u);
const path='doc/audit/depot-complete-cohort-'+cohortId+'.json';
const common={schemaVersion:1,cohortId,preparedAt,cases:Object.fromEntries(frozen.cases.map(row=>[row.caseId,{sourceRevision:row.sourceRevision,baseRevision:row.baseRevision,manifestSha256:row.manifestSha256}])),routes:Object.fromEntries(Object.entries(frozen.routes).map(([routeId,row])=>[routeId,{caseId:row.caseId,harnessRevision:frozen.harnesses[row.harnessKey].harnessRevision,workflow:row.workflow,provider:row.provider}])),registration:{path:'.depot/manifests/complete-routing.json',harnessRevision:frozen.harnesses.root.harnessRevision,caseCopies:24,primaryChecks:770,externalChecks:33,routeCount:20},policy:{scorecard:'Sequential terminal dispatches under the unchanged current quota policy; live default-branch analysis with publication disabled.',historicalSources:'Exact immutable source revisions; retain source failures and do not credit unexecuted assertions.',android:'Consume only the common-bound native.producers native-android artifact and provenance.'}};
writeFileSync('real-common-cohort-candidate.json',JSON.stringify({phase:'prepared',cohortId,path,preparedAt},null,2)+'\n',{flag:'wx'});
writeFileSync(join(main,path),JSON.stringify(common,null,2)+'\n',{flag:'wx'});
execFileSync('dprint',['fmt',path],{cwd:main,stdio:'inherit'});
const bytes=readFileSync(join(main,path));assert(bytes.length<1024*1024);
const manifestSha256=createHash('sha256').update(bytes).digest('hex');
execFileSync('git',['add','--',path],{cwd:main});
execFileSync('git',['commit','--message','docs(audit): freeze real complete replay cohort','--',path],{cwd:main,stdio:'inherit'});
const committedAt=execFileSync('git',['rev-parse','HEAD'],{cwd:main,encoding:'utf8'}).trim();assert.deepEqual(execFileSync('git',['show',committedAt+':'+path],{cwd:main}),bytes);
writeFileSync('real-common-cohort-candidate.json',JSON.stringify({phase:'committed',cohortId,path,preparedAt,manifestSha256,bytes:bytes.length,committedAt},null,2)+'\n');
console.log(JSON.stringify({cohortId,path,manifestSha256,bytes:bytes.length,committedAt,requestedAtNotYetChosen:true}));
'''

[tasks.publish-and-confirm-real-common-cohort]
shell = "node --input-type=module-typescript -e"
run = '''
const {execFileSync}=await import('node:child_process');
const {readFileSync,writeFileSync}=await import('node:fs');
const {join}=await import('node:path');
const {homedir}=await import('node:os');
const {createHash}=await import('node:crypto');
const {strict:assert}=await import('node:assert');
const candidate=JSON.parse(readFileSync('real-common-cohort-candidate.json','utf8'));assert.equal(candidate.phase,'committed');
const main=join(homedir(),'Monochromatic');
const expected=readFileSync(join(main,candidate.path));const sha=bytes=>createHash('sha256').update(bytes).digest('hex');assert.equal(sha(expected),candidate.manifestSha256);
assert.deepEqual(execFileSync('git',['show','HEAD:'+candidate.path],{cwd:main}),expected);
assert.equal(execFileSync('git',['branch','--show-current'],{cwd:main,encoding:'utf8'}).trim(),'main');
const head=execFileSync('git',['rev-parse','HEAD'],{cwd:main,encoding:'utf8'}).trim();
execFileSync('git',['push','origin','HEAD'],{cwd:main,stdio:'inherit'});
const remote=execFileSync('git',['ls-remote','origin','refs/heads/main'],{cwd:main,encoding:'utf8'}).trim().split(/\s/u)[0];assert.equal(remote,head);
const endpoint='repos/Aquaticats/Monochromatic/contents/'+candidate.path+'?ref=main';
const envelope=JSON.parse(execFileSync('gh',['api','--method','GET','--header','Accept: application/vnd.github.object+json',endpoint],{cwd:main,encoding:'utf8',maxBuffer:4*1024*1024}));
assert.equal(envelope.type,'file');assert.equal(envelope.path,candidate.path);assert.equal(envelope.encoding,'base64');
const encoded=envelope.content.replaceAll('\r','').replaceAll('\n','');const bytes=Buffer.from(encoded,'base64');assert.equal(bytes.toString('base64'),encoded);assert.equal(bytes.length,envelope.size);assert.deepEqual(bytes,expected);assert.equal(sha(bytes),candidate.manifestSha256);
const gitBlob=createHash('sha1').update('blob '+bytes.length+'\0').update(bytes).digest('hex');assert.equal(envelope.sha,gitBlob);
const publishedAt=new Date().toISOString();
const receipt={...candidate,phase:'published-and-byte-verified',publishedAt,verifiedRemoteRevision:remote,repository:'Aquaticats/Monochromatic',ref:'main',endpoint,mediaType:'application/vnd.github.object+json',gitBlob,exactPublishedBytesVerified:true,requestedAtNotYetChosen:true};
writeFileSync('real-common-cohort-publication.json',JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify(receipt));
'''

[tasks.dispatch-real-coherent-route]
shell = "node --input-type=module-typescript -e"
run = '''
const {execFileSync,spawnSync}=await import('node:child_process');
const {readFileSync,writeFileSync,existsSync,mkdirSync}=await import('node:fs');
const {join,basename}=await import('node:path');
const {createHash}=await import('node:crypto');
const {strict:assert}=await import('node:assert');
const routeId=process.env.DEPOT_COHERENT_ROUTE;
const frozen=JSON.parse(readFileSync('frozen-case-registration.json','utf8'));
const publication=JSON.parse(readFileSync('real-common-cohort-publication.json','utf8'));
assert(publication.exactPublishedBytesVerified);assert.equal(publication.phase,'published-and-byte-verified');
const route=frozen.routes[routeId];assert(route,'Unknown frozen route: '+routeId);
const harness=frozen.harnesses[route.harnessKey];
const git=args=>execFileSync('git',args,{cwd:harness.worktree,encoding:'utf8'}).trim();
assert.equal(git(['rev-parse','HEAD']),harness.harnessRevision);assert.equal(git(['branch','--show-current']),harness.ref);assert.equal(git(['status','--porcelain']),'');
assert.equal(git(['ls-remote','origin','refs/heads/'+harness.ref]).split(/\s/u)[0],harness.harnessRevision);
const common=JSON.parse(execFileSync('git',['show',publication.committedAt+':'+publication.path],{cwd:harness.worktree,encoding:'utf8'}));
assert.equal(common.routes[routeId].harnessRevision,harness.harnessRevision);assert.equal(common.routes[routeId].workflow,route.workflow);
if(!existsSync('real-cohort-request-clock.json')){const requestedAt=new Date().toISOString();assert(Date.parse(requestedAt)>=Date.parse(publication.publishedAt));writeFileSync('real-cohort-request-clock.json',JSON.stringify({cohortId:publication.cohortId,manifestSha256:publication.manifestSha256,publishedAt:publication.publishedAt,requestedAt},null,2)+'\n',{flag:'wx'})}
const clock=JSON.parse(readFileSync('real-cohort-request-clock.json','utf8'));assert.equal(clock.cohortId,publication.cohortId);assert.equal(clock.manifestSha256,publication.manifestSha256);
assert.equal(new Date(clock.requestedAt).toISOString(),clock.requestedAt);
const input={cohort_id:clock.cohortId,manifest_sha256:clock.manifestSha256,requested_at:clock.requestedAt,...route.requiredInputValues};
mkdirSync('real-cohort-dispatches',{recursive:true,mode:0o700});
const receiptPath='real-cohort-dispatches/'+routeId+'.json';
assert(!existsSync(receiptPath),'Existing dispatch receipt requires reconciliation; never dispatch the route blindly twice');
if(routeId.endsWith('.scorecard')){const order=['toml.scorecard','logger.scorecard','native.scorecard','desktop.scorecard'];const position=order.indexOf(routeId);assert(position>=0);if(position>0){const prior=JSON.parse(readFileSync('real-cohort-dispatches/'+order[position-1]+'.terminal.json','utf8'));assert.equal(prior.run.status,'completed');assert.equal(prior.dispatch.cohortId,clock.cohortId)}}
const command=route.provider==='depot'?'depot':'gh';
const args=command==='depot'?['ci','dispatch','--repo','Aquaticats/Monochromatic','--workflow',basename(route.workflow),'--ref',harness.ref,'--org','l4zncjjbj5','--output','json',...Object.entries(input).flatMap(([key,value])=>['--input',key+'='+value])]:['workflow','run',basename(route.workflow),'--repo','Aquaticats/Monochromatic','--ref',harness.ref,'--json'];
const receipt={phase:'dispatch-started',routeId,caseId:route.caseId,provider:route.provider,cohortId:clock.cohortId,manifestSha256:clock.manifestSha256,requestedAt:clock.requestedAt,publishedAt:publication.publishedAt,harnessRevision:harness.harnessRevision,harnessRef:harness.ref,workflow:route.workflow,workflowSha256:createHash('sha256').update(readFileSync(join(harness.worktree,route.workflow))).digest('hex'),command,args,inputs:input,startedAt:new Date().toISOString()};
writeFileSync(receiptPath,JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});
const result=spawnSync(command,args,{cwd:harness.worktree,encoding:'utf8',input:command==='gh'?JSON.stringify(input):undefined,maxBuffer:8*1024*1024});
Object.assign(receipt,{phase:'dispatch-returned',returnedAt:new Date().toISOString(),exitCode:result.status,signal:result.signal,error:result.error?.message,stdout:result.stdout,stderr:result.stderr});
writeFileSync(receiptPath,JSON.stringify(receipt,null,2)+'\n');
assert.equal(result.status,0,result.stderr||result.error?.message||'Provider dispatch failed; reconcile this receipt before any retry');
if(command==='depot'){const response=JSON.parse(result.stdout);const runId=response.run_id??response.runId;assert.match(runId??'',/^[a-z0-9]+$/u);assert.equal(response.org_id??response.orgId,'l4zncjjbj5');Object.assign(receipt,{phase:'run-created',runId,url:'https://depot.dev/orgs/l4zncjjbj5/workflows/'+runId,response})}
else{const match=result.stdout.match(/https:\/\/github\.com\/Aquaticats\/Monochromatic\/actions\/runs\/(\d+)/u);assert(match,'No returned GitHub run URL; reconcile the recorded dispatch without redispatch');const runId=match[1];Object.assign(receipt,{runId,url:match[0]});writeFileSync(receiptPath,JSON.stringify(receipt,null,2)+'\n');const run=JSON.parse(execFileSync('gh',['api','repos/Aquaticats/Monochromatic/actions/runs/'+runId],{cwd:harness.worktree,encoding:'utf8',maxBuffer:8*1024*1024}));assert.equal(run.head_sha,harness.harnessRevision);assert.equal(run.head_branch,harness.ref);assert.equal(run.event,'workflow_dispatch');assert(run.path===route.workflow||run.path.startsWith(route.workflow+'@'));Object.assign(receipt,{phase:'run-created',run})}
writeFileSync(receiptPath,JSON.stringify(receipt,null,2)+'\n');
console.log(JSON.stringify({routeId,runId:receipt.runId,url:receipt.url,harnessRevision:receipt.harnessRevision,cohortId:receipt.cohortId,requestedAt:receipt.requestedAt}));
'''

[tasks.dispatch-other-real-coherent-routes]
shell = "node --input-type=module-typescript -e"
run = '''
const {execFileSync}=await import('node:child_process');
const {readFileSync,existsSync}=await import('node:fs');
const {strict:assert}=await import('node:assert');
const frozen=JSON.parse(readFileSync('frozen-case-registration.json','utf8'));
const first=JSON.parse(readFileSync('real-cohort-dispatches/native.producers.json','utf8'));assert.equal(first.phase,'run-created');
const routes=Object.keys(frozen.routes).filter(routeId=>routeId!=='native.producers'&&!routeId.endsWith('.scorecard'));
assert.equal(routes.length,15);
for(const routeId of [...routes,'toml.scorecard']){const path='real-cohort-dispatches/'+routeId+'.json';if(existsSync(path)){const prior=JSON.parse(readFileSync(path,'utf8'));assert.equal(prior.phase,'run-created','Reconcile incomplete existing receipt for '+routeId);assert.equal(prior.cohortId,first.cohortId);console.log(JSON.stringify({routeId,existingRun:prior.runId}));continue}execFileSync('mise',['run','dispatch-real-coherent-route'],{cwd:process.cwd(),env:{...process.env,DEPOT_COHERENT_ROUTE:routeId},stdio:'inherit'})}
'''

[tasks.wait-real-coherent-scorecards]
shell = "node --input-type=module-typescript -e"
run = '''
const {execFileSync,spawnSync}=await import('node:child_process');
const {readFileSync,writeFileSync,existsSync,openSync,closeSync}=await import('node:fs');
const {strict:assert}=await import('node:assert');
const order=['toml.scorecard','logger.scorecard','native.scorecard','desktop.scorecard'];
for(const routeId of order){const prefix='real-cohort-dispatches/'+routeId;const terminalPath=prefix+'.terminal.json';if(existsSync(terminalPath)){const row=JSON.parse(readFileSync(terminalPath,'utf8'));assert.equal(row.run.status,'completed');console.log(JSON.stringify({routeId,existingTerminal:row.dispatch.runId,conclusion:row.run.conclusion}));continue}if(!existsSync(prefix+'.json'))execFileSync('mise',['run','dispatch-real-coherent-route'],{cwd:process.cwd(),env:{...process.env,DEPOT_COHERENT_ROUTE:routeId},stdio:'inherit'});const dispatch=JSON.parse(readFileSync(prefix+'.json','utf8'));assert.equal(dispatch.phase,'run-created');const fd=openSync(prefix+'.watch.log','a',0o600);let watched;try{watched=spawnSync('gh',['run','watch',dispatch.runId,'--repo','Aquaticats/Monochromatic','--compact','--exit-status','--interval','30'],{stdio:['ignore',fd,fd]})}finally{closeSync(fd)}const run=JSON.parse(execFileSync('gh',['api','repos/Aquaticats/Monochromatic/actions/runs/'+dispatch.runId],{encoding:'utf8',maxBuffer:8*1024*1024}));const jobs=JSON.parse(execFileSync('gh',['api','repos/Aquaticats/Monochromatic/actions/runs/'+dispatch.runId+'/jobs?per_page=100'],{encoding:'utf8',maxBuffer:8*1024*1024}));assert.equal(run.status,'completed');assert.equal(run.head_sha,dispatch.harnessRevision);assert.equal(jobs.total_count,jobs.jobs.length);const receipt={observedAt:new Date().toISOString(),dispatch,watchExitCode:watched.status,watchSignal:watched.signal,watchError:watched.error?.message,run,jobs};writeFileSync(terminalPath,JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({routeId,runId:dispatch.runId,status:run.status,conclusion:run.conclusion,jobs:jobs.jobs.map(job=>({id:job.id,name:job.name,conclusion:job.conclusion}))}))}
'''

[tasks.wait-real-coherent-normal-routes]
shell = "node --input-type=module-typescript -e"
run = '''
const {execFileSync,spawn}=await import('node:child_process');
const {readFileSync,writeFileSync,existsSync,openSync,closeSync}=await import('node:fs');
const {once}=await import('node:events');
const {strict:assert}=await import('node:assert');
const frozen=JSON.parse(readFileSync('frozen-case-registration.json','utf8'));
const routes=Object.keys(frozen.routes).filter(routeId=>!routeId.endsWith('.scorecard'));assert.equal(routes.length,16);
const results=await Promise.allSettled(routes.map(async routeId=>{const prefix='real-cohort-dispatches/'+routeId;const terminalPath=prefix+'.terminal.json';if(existsSync(terminalPath)){const row=JSON.parse(readFileSync(terminalPath,'utf8'));console.log(JSON.stringify({routeId,existingTerminal:row.dispatch.runId}));return {routeId,existing:true}}const dispatch=JSON.parse(readFileSync(prefix+'.json','utf8'));assert.equal(dispatch.phase,'run-created');const depot=dispatch.provider==='depot';const stdout=openSync(prefix+(depot?'.status.json':'.watch.log'),'a',0o600);const stderr=depot?openSync(prefix+'.watch.stderr.log','a',0o600):stdout;const command=depot?'depot':'gh';const args=depot?['ci','status',dispatch.runId,'--org','l4zncjjbj5','--wait','--output','json']:['run','watch',dispatch.runId,'--repo','Aquaticats/Monochromatic','--compact','--exit-status','--interval','30'];let code,signal;try{const child=spawn(command,args,{stdio:['ignore',stdout,stderr]});[code,signal]=await once(child,'exit')}finally{closeSync(stdout);if(stderr!==stdout)closeSync(stderr)}let receipt;if(depot){const status=JSON.parse(readFileSync(prefix+'.status.json','utf8'));receipt={observedAt:new Date().toISOString(),dispatch,watchExitCode:code,watchSignal:signal,status};writeFileSync(terminalPath,JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({routeId,runId:dispatch.runId,watchExitCode:code,providerStatusKeys:Object.keys(status)}))}else{const run=JSON.parse(execFileSync('gh',['api','repos/Aquaticats/Monochromatic/actions/runs/'+dispatch.runId],{encoding:'utf8',maxBuffer:8*1024*1024}));const jobs=JSON.parse(execFileSync('gh',['api','repos/Aquaticats/Monochromatic/actions/runs/'+dispatch.runId+'/jobs?per_page=100'],{encoding:'utf8',maxBuffer:8*1024*1024}));assert.equal(run.status,'completed');assert.equal(run.head_sha,dispatch.harnessRevision);assert.equal(jobs.total_count,jobs.jobs.length);receipt={observedAt:new Date().toISOString(),dispatch,watchExitCode:code,watchSignal:signal,run,jobs};writeFileSync(terminalPath,JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({routeId,runId:dispatch.runId,status:run.status,conclusion:run.conclusion,jobs:jobs.total_count}))}return {routeId,runId:dispatch.runId,watchExitCode:code}}));
writeFileSync('real-coherent-normal-waits.json',JSON.stringify(results.map(row=>row.status==='fulfilled'?row:{status:row.status,reason:String(row.reason)}),null,2)+'\n');
for(const row of results)if(row.status==='rejected')throw row.reason;
'''

[tasks.verify-real-provider-bindings]
shell = "node --input-type=module-typescript -e"
run = '''
const {execFileSync}=await import('node:child_process');
const {readFileSync,writeFileSync}=await import('node:fs');
const {strict:assert}=await import('node:assert');
const frozen=JSON.parse(readFileSync('frozen-case-registration.json','utf8'));
const rows=[];
for(const [routeId,route] of Object.entries(frozen.routes).filter(([,route])=>route.provider==='depot')){const dispatch=JSON.parse(readFileSync('real-cohort-dispatches/'+routeId+'.json','utf8'));assert.equal(dispatch.phase,'run-created');const run=JSON.parse(execFileSync('depot',['ci','run','show',dispatch.runId,'--org','l4zncjjbj5','--output','json'],{encoding:'utf8',maxBuffer:4*1024*1024}));assert.equal(run.org_id,'l4zncjjbj5');assert.equal(run.repo,'Aquaticats/Monochromatic');assert.equal(run.head_sha,dispatch.harnessRevision);assert.equal(run.sha,dispatch.harnessRevision);assert.equal(run.ref,'refs/heads/'+dispatch.harnessRef);assert.equal(run.trigger,'workflow_dispatch');rows.push({routeId,verifiedAt:new Date().toISOString(),run});console.log(JSON.stringify({routeId,runId:run.run_id,status:run.status,headShaVerified:run.head_sha}))}
assert.equal(rows.length,7);
writeFileSync('real-cohort-depot-provider-bindings.json',JSON.stringify({verifiedAt:new Date().toISOString(),rows,actualConsumerAcceptance:false},null,2)+'\n');
'''
